function deriveInstanceAiSetupState(settings) {
    const modelSource = settings.modelEnvConfigured
        ? 'env'
        : settings.modelCredentialId && settings.modelName
            ? 'ui'
            : 'none';
    const sandboxCredentialId = settings.sandboxProvider === 'daytona'
        ? settings.daytonaCredentialId
        : settings.n8nSandboxCredentialId;
    const sandboxSource = !settings.sandboxEnabled
        ? 'none'
        : settings.sandboxEnvConfigured
            ? 'env'
            : sandboxCredentialId
                ? 'ui'
                : 'none';
    const webSearchSource = settings.searchCredentialId
        ? 'ui'
        : settings.searchEnvConfigured
            ? 'env'
            : settings.searchDisabled
                ? 'disabled'
                : 'none';
    return {
        modelSource,
        sandboxSource,
        sandboxType: sandboxSource === 'none' ? null : settings.sandboxProvider,
        sandboxCredentialId,
        webSearchSource,
        setupCompleted: modelSource !== 'none' && sandboxSource !== 'none' && webSearchSource !== 'none',
    };
}
