function getRenderHint(toolName) {
    if (toolName === 'task-control')
        return 'tasks';
    if (toolName === 'build-workflow' || toolName === 'build-workflow-with-agent')
        return 'builder';
    if (toolName === 'research-with-agent')
        return 'researcher';
    if (toolName === 'create-tasks')
        return 'planner';
    if (toolName === 'eval-setup-with-agent')
        return 'eval-setup';
    if (toolName === 'list_skills' || toolName === 'load_skill')
        return 'skill';
    return 'default';
}
